CREATE TABLE IF NOT EXISTS app_specialties (id VARCHAR(64) PRIMARY KEY, code VARCHAR(8) NOT NULL, name VARCHAR(255) NOT NULL, qualification VARCHAR(512) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS app_groups (id VARCHAR(64) PRIMARY KEY, name VARCHAR(64) NOT NULL UNIQUE, admission_year SMALLINT NOT NULL, graduation_year SMALLINT NOT NULL DEFAULT 2026, specialty_id VARCHAR(64) NOT NULL, FOREIGN KEY(specialty_id) REFERENCES app_specialties(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS app_students (id VARCHAR(64) PRIMARY KEY, group_id VARCHAR(64) NOT NULL, name VARCHAR(255) NOT NULL, FOREIGN KEY(group_id) REFERENCES app_groups(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS app_subjects (id VARCHAR(64) PRIMARY KEY, specialty_id VARCHAR(64) NOT NULL, name VARCHAR(255) NOT NULL, FOREIGN KEY(specialty_id) REFERENCES app_specialties(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS app_users (id VARCHAR(64) PRIMARY KEY, name VARCHAR(255) NOT NULL, login VARCHAR(64) NOT NULL UNIQUE, role ENUM('student','admin','analyst') NOT NULL, student_id VARCHAR(64) NULL UNIQUE, password_hash CHAR(64) NOT NULL, password_salt CHAR(32) NOT NULL, FOREIGN KEY(student_id) REFERENCES app_students(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS app_tests (id VARCHAR(64) PRIMARY KEY, name VARCHAR(255) NOT NULL, subject_id VARCHAR(64) NULL, minutes SMALLINT NOT NULL, published BOOLEAN NOT NULL, FOREIGN KEY(subject_id) REFERENCES app_subjects(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS app_variants (id VARCHAR(64) PRIMARY KEY, test_id VARCHAR(64) NOT NULL, name VARCHAR(100) NOT NULL, position INT NOT NULL, FOREIGN KEY(test_id) REFERENCES app_tests(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS app_questions (id VARCHAR(64) PRIMARY KEY, variant_id VARCHAR(64) NOT NULL, text MEDIUMTEXT NOT NULL, correct_option_id VARCHAR(64) NOT NULL, position INT NOT NULL, FOREIGN KEY(variant_id) REFERENCES app_variants(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS app_options (id VARCHAR(64) PRIMARY KEY, question_id VARCHAR(64) NOT NULL, text MEDIUMTEXT NOT NULL, position INT NOT NULL, FOREIGN KEY(question_id) REFERENCES app_questions(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS app_assignments (test_id VARCHAR(64) NOT NULL, group_id VARCHAR(64) NOT NULL, PRIMARY KEY(test_id,group_id), FOREIGN KEY(test_id) REFERENCES app_tests(id), FOREIGN KEY(group_id) REFERENCES app_groups(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS app_attempts (id VARCHAR(64) PRIMARY KEY, student_id VARCHAR(64) NOT NULL, test_id VARCHAR(64) NOT NULL, payload JSON NOT NULL, UNIQUE(student_id,test_id), FOREIGN KEY(student_id) REFERENCES app_students(id), FOREIGN KEY(test_id) REFERENCES app_tests(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS app_settings (id TINYINT PRIMARY KEY, revision BIGINT UNSIGNED NOT NULL, next_user_number INT UNSIGNED NOT NULL, scale JSON NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS app_sessions (token_hash CHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL, expires_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES app_users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS app_auth_throttle (id CHAR(64) PRIMARY KEY, count INT NOT NULL, window_start DATETIME NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS app_user_passwords (
 user_id VARCHAR(64) NOT NULL PRIMARY KEY,
 envelope TEXT NOT NULL,
 password_hash VARCHAR(64) NOT NULL,
 password_salt VARCHAR(32) NOT NULL,
 FOREIGN KEY (user_id) REFERENCES app_users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS app_subject_assignments (subject_id VARCHAR(64) NOT NULL, group_id VARCHAR(64) NOT NULL, PRIMARY KEY(subject_id,group_id), FOREIGN KEY(subject_id) REFERENCES app_subjects(id), FOREIGN KEY(group_id) REFERENCES app_groups(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS app_migrations (id VARCHAR(100) PRIMARY KEY, applied_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
